    _purchase = function (this, slot, target, accessorySlots, multipleCount, argStrs)
      assert(multipleCount > 0)
      wdmWuKongVendor.VendorPluginProgressHelper.AssertLegalIfProgressVendor(slot)
      local args =_getArgs(argStrs)
      
      -- will set context in validate
      _purchaseValidate(this, slot, target, accessorySlots, multipleCount, args):AssertPass()
      _setContext(this, slot, target, accessorySlots, multipleCount, args)
      
      local cfgProducts =wdmWuKongVendor.VendorPluginProgressHelper.GetIndexProducts(this._cacheProducts, slot)
      local cfgCosts =wdmWuKongVendor.VendorPluginProgressHelper.GetIndexCosts(this._cacheCosts, slot)
      local cfgPostActions =wdmWuKongVendor.VendorPluginProgressHelper.GetPostActions(this._cachePostActions, slot)
      
      
      local result =wdmWuKongVendor.PurchaseResult()
      result.VendorId = this.Cfg.Id
      
      -- predict cost, 有时候, 不需要购买很多次, 此处进行预测
      if multipleCount > 1 then
        local default, minCount = wdmWuKongVendor.ProductProcessorHelper.TryPredictMinCost(cfgProducts, slot, target, accessorySlots)
        if default then
          if multipleCount > minCount then
            multipleCount = minCount
          end
        end
      end
      
      local default, hooks = wdmWuKongCore.PluginsExtension.TryGetPlugin(slot, nil, wdmWuKongVendor.VendorHooksPlugin)
      local hasHooks =default
      
      -- 消耗钩子
      if hasHooks then
        local costResult =hooks:HookReplaceCost(slot, target, accessorySlots, multipleCount, args, result)
        if costResult ~= nil then
          -- 说明钩子成功执行
          result.Costs = costResult
        end
      end
      
      
      -- 没有消耗钩子结果, 使用配置进行消耗
      if result.Costs == nil then
        result.Costs = wdmWuKongVendor.CostPluginHelper.DoCost(cfgCosts, slot, target, accessorySlots, multipleCount)
        wdmWuKongVendor.CostPluginHelper.DoRecord(cfgCosts, slot, result)
      end
      
      local rewards =nil
      
      -- 奖励钩子
      if hasHooks then
        rewards = hooks:HookReplaceReward(slot, target, accessorySlots, multipleCount, args)
        if rewards ~= nil then
          -- 说明钩子成功执行
          result.Receive = rewards
        end
      end
      
      
      -- 没有奖励钩子结果, 使用配置进行奖励
      if result.Receive == nil then
        -- receive
        rewards = wdmWuKongVendor.ProductProcessorHelper.Fill(cfgProducts, slot, target, multipleCount)
        result.Receive = rewards
      end
      
      
      
      -- executed count 
      slot:getElement():setCount(slot:getElement():getCount() + multipleCount)
      
      -- post Action
      for i = 0, multipleCount - 1 do
        _executePostAction(this, slot, cfgPostActions)
      end
      
      -- 购买后的钩子
      if hasHooks then
        hooks:HookPurchased(slot, target, accessorySlots, multipleCount, args, result)
      end
      
      
      _resetContext(this, slot)
      
      _updateInnerCount(this, slot)
      
      -- 进度增加
      local _, progressVendorPlugin = wdmWuKongCore.PluginsExtension.TryGetPlugin(slot, nil, wdmWuKongVendor.ProgressVendorPlugin)
      if progressVendorPlugin ~= nil then
        progressVendorPlugin:AddProgress(slot)
      end
      
      return result
    end
